def eval_apply(expr, env, tail):
    args_list = cdr_to_list(expr.cdr)
    if len(args_list) < 2:
        raise SchemeError("apply requires at least 2 arguments")

    proc = eval(args_list[0], env, False)
    # args_list[1] through args_list[-2] are regular args
    # args_list[-1] is the list
    regular_args = []
    for arg_expr in args_list[1:-1]:
        regular_args.append(eval(arg_expr, env, False))
    lst = eval(args_list[-1], env, False)

    # lst must be a proper list
    elements = list_to_python(lst)
    all_args = regular_args + elements

    if isinstance(proc, Closure):
        check_arity(proc.formals, all_args)
        if tail:
            return TailCall(proc, all_args)
        else:
            new_env = make_call_env(proc.formals, all_args, proc.env)
            return eval_body(proc.body, new_env, False)
    elif isinstance(proc, Builtin):
        return proc.func(all_args)
    else:
        raise SchemeError("not a procedure")
