```python
def tokenize(source):
    tokens = []
    i = 0
    while i < len(source):
        c = source[i]
        if c in ' \t\n\r':
            i += 1
        elif c == ';':
            # skip to end of line
            while i < len(source) and source[i] != '\n':
                i += 1
        elif c == '(':
            tokens.append(('(', None))
            i += 1
        elif c == ')':
            tokens.append((')', None))
            i += 1
        elif c == '"':
            # read string
            i += 1
            s = []
            while i < len(source) and source[i] != '"':
                if source[i] == '\\':
                    i += 1
                    if i >= len(source):
                        raise SchemeError("unterminated string")
                    nc = source[i]
                    if nc == '"': s.append('"')
                    elif nc == '\\': s.append('\\')
                    elif nc == 'n': s.append('\n')
                    else: raise SchemeError("invalid escape")
                else:
                    s.append(source[i])
                i += 1
            if i >= len(source):
                raise SchemeError("unterminated string")
            i += 1  # skip closing "
            tokens.append(('string', ''.join(s)))
        elif c == "'":
            tokens.append(("'", None))
            i += 1
        else:
            # read a word token
            start = i
            while i < len(source) and source[i] not in ' \t\n\r()";\'':
                i += 1
            word = source[start:i]
            tokens.append(('word', word))
    return tokens
```

