def parse_all(tokens):
    forms = []
    pos = [0]
    while pos[0] < len(tokens):
        forms.append(parse_form(tokens, pos))
    return forms

def parse_form(tokens, pos):
    if pos[0] >= len(tokens):
        raise SchemeError("unexpected end of input")
    tok_type, tok_val = tokens[pos[0]]
    if tok_type == '(':
        pos[0] += 1
        return parse_list(tokens, pos)
    elif tok_type == ')':
        raise SchemeError("unexpected )")
    elif tok_type == "'":
        pos[0] += 1
        datum = parse_form(tokens, pos)
        return Pair(Symbol('quote'), Pair(datum, NIL))
    elif tok_type == 'string':
        pos[0] += 1
        return tok_val
    elif tok_type == 'word':
        pos[0] += 1
        return parse_word(tok_val)
    else:
        raise SchemeError("unexpected token")

def parse_list(tokens, pos):
    elements = []
    dotted = False
    dot_val = None
    while True:
        if pos[0] >= len(tokens):
            raise SchemeError("unbalanced (")
        tok_type, tok_val = tokens[pos[0]]
        if tok_type == ')':
            pos[0] += 1
            break
        elif tok_type == 'word' and tok_val == '.' and not dotted:
            # Check if this is a dot
            # Need at least one element before
            if not elements:
                raise SchemeError("dot without preceding element")
            pos[0] += 1
            dotted = True
            # Parse exactly one datum
            dot_val = parse_form(tokens, pos)
            # Next must be )
            if pos[0] >= len(tokens) or tokens[pos[0]][0] != ')':
                raise SchemeError("expected ) after dotted value")
            pos[0] += 1
            break
        else:
            if dotted:
                raise SchemeError("too many elements after dot")
            elements.append(parse_form(tokens, pos))

    # Build list
    if dotted:
        result = dot_val
        for elem in reversed(elements):
            result = Pair(elem, result)
        return result
    else:
        result = NIL
        for elem in reversed(elements):
            result = Pair(elem, result)
        return result
