def check_arity(formals, args):
    if isinstance(formals, Symbol):
        return  # any number of args
    # formals is a list (possibly dotted)
    required = []
    rest = None
    cur = formals
    while isinstance(cur, Pair):
        if isinstance(cur.cdr, Symbol):
            rest = cur.cdr
            break
        elif isinstance(cur.cdr, Nil):
            required.append(cur.car)
            break
        else:
            required.append(cur.car)
            cur = cur.cdr
    # Check
    if rest is None:
        # Fixed arity
        if len(args) != len(required):
            raise SchemeError(f"wrong number of arguments: expected {len(required)}, got {len(args)}")
    else:
        if len(args) < len(required):
            raise SchemeError(f"wrong number of arguments: expected at least {len(required)}, got {len(args)}")
