def make_call_env(formals, args, parent_env):
    env = Env(parent_env)
    if isinstance(formals, Symbol):
        env.define(formals.name, list_to_scheme(args))
    else:
        required = []
        rest = None
        cur = formals
        while isinstance(cur, Pair):
            if isinstance(cur.cdr, Symbol):
                rest = cur.cdr
                required.append(cur.car)
                break
            elif isinstance(cur.cdr, Nil):
                required.append(cur.car)
                break
            else:
                required.append(cur.car)
                cur = cur.cdr

        for i, sym in enumerate(required):
            env.define(sym.name, args[i])
        if rest is not None:
            env.define(rest.name, list_to_scheme(args[len(required):]))
    return env
```

