def int_to_base(n, radix):
    if n == 0:
        return '0'
    negative = n < 0
    n = abs(n)
    digits = []
    while n > 0:
        d = n % radix
        if d < 10:
            digits.append(chr(ord('0') + d))
        else:
            digits.append(chr(ord('a') + d - 10))
        n //= radix
    result = ''.join(reversed(digits))
    if negative:
        result = '-' + result
    return result
```

