def quotient(a, b):
    # Truncates toward zero
    q = abs(a) // abs(b)
    if (a < 0) ^ (b < 0):
        q = -q
    return q

def remainder(a, b):
    # Sign of dividend (a)
    # Python's % has sign of divisor, so we need to adjust
    q = quotient(a, b)
    return a - q * b

def modulo(a, b):
    # Sign of divisor (b)
    # Python's % already does this
    return a % b
