    while isinstance(cur, Pair):
        binding = cur.car
        if not isinstance(binding, Pair) or not isinstance(binding.car, Symbol):
            raise SchemeError("invalid letrec binding")
        name = binding.car.name
        names.append(name)
        inits.append(binding.cdr.car)
        letrec_env.define(name, UNINITIALIZED)
        cur = cur.cdr

    # Second pass: evaluate inits in order
    for name, init in zip(names, inits):
        val = eval(init, letrec_env, False)
        letrec_env.set(name, val)

    return eval_body(body_forms, letrec_env, tail)
