```python
"""A Scheme interpreter for a small, precisely specified subset."""

import sys
import re
import threading

# Disable the int-to-str digit limit (Python 3.11+)
if hasattr(sys, 'set_int_max_str_digits'):
    sys.set_int_max_str_digits(0)

# Increase recursion limit for non-tail recursion
sys.setrecursionlimit(500000)

# ─── Data Types ───────────────────────────────────────────────────────────────

class SchemeError(Exception):
    def __init__(self, msg, output=''):
        super().__init__(msg)
        self.output = output

class Symbol:
    __slots__ = ('name',)
    def __init__(self, name):
        self.name = name
    def __repr__(self):
        return self.name

class Pair:
    __slots__ = ('car', 'cdr')
    def __init__(self, car, cdr):
        self.car = car
        self.cdr = cdr

class _Nil:
    def __repr__(self):
        return '()'

NIL = _Nil()

class _Unspecified:
    def __repr__(self):
        return ''

UNSPECIFIED = _Unspecified()

class _Uninitialized:
    pass

UNINITIALIZED = _Uninitialized()

class Closure:
    __slots__ = ('formals', 'body', 'env')
    def __init__(self, formals, body, env):
        self.formals = formals
        self.body = body
        self.env = env

class Builtin:
    __slots__ = ('name', 'func')
    def __init__(self, name, func):
        self.name = name
        self.func = func

class TailCall:
    __slots__ = ('proc', 'args')
    def __init__(self, proc, args):
        self.proc = proc
        self.args = args

# ─── Environment ──────────────────────────────────────────────────────────────

class Env:
    __slots__ = ('vars', 'parent')
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

    def lookup(self, name):
        env = self
        while env is not None:
            if name in env.vars:
                val = env.vars[name]
                if isinstance(val, _Uninitialized):
                    raise SchemeError(f"uninitialized variable: {name}")
                return val
            env = env.parent
        raise SchemeError(f"unbound variable: {name}")

    def define(self, name, value):
        self.vars[name] = value

    def set(self, name, value):
        env = self
        while env is not None:
            if name in env.vars:
                env.vars[name] = value
                return
            env = env.parent
        raise SchemeError(f"set!: unbound variable: {name}")

# ─── Reader ───────────────────────────────────────────────────────────────────

INT_RE = re.compile(r'^[+-]?[0-9]+$')

def tokenize(source):
    tokens = []
    i = 0
    n = len(source)
    while i < n:
        c = source[i]
        if c in ' \t\n\r':
            i += 1
        elif c == ';':
            while i < n and source[i] != '\n':
                i += 1
        elif c == '(':
            tokens.append(('(', None))
            i += 1
        elif c == ')':
            tokens.append((')', None))
            i += 1
        elif c == '"':
            i += 1
            s = []
            while i < n and source[i] != '"':
                if source[i] == '\\':
                    i += 1
                    if i >= n:
                        raise SchemeError("unterminated string escape")
                    nc = source[i]
                    if nc == '"': s.append('"')
                    elif nc == '\\': s.append('\\')
                    elif nc == 'n': s.append('\n')
                    else: raise SchemeError(f"invalid escape: \\{nc}")
                else:
                    s.append(source[i])
                i += 1
            if i >= n:
                raise SchemeError("unterminated string")
            i += 1  # skip closing "
            tokens.append(('string', ''.join(s)))
        elif c == "'":
            tokens.append(("'", None))
            i += 1
        else:
            start = i
            while i < n and source[i] not in ' \t\n\r()";\'':
                i += 1
            tokens.append(('word', source[start:i]))
    return tokens

def parse_all(tokens):
    forms = []
    pos = [0]
    while pos[0] < len(tokens):
        forms.append(parse_form(tokens, pos))
    return forms

def parse_form(tokens, pos):
    if pos[0] >= len(tokens):
        raise SchemeError("unexpected end of input")
    tok_type, tok_val = tokens[pos[0]]
    if tok_type == '(':
        pos[0] += 1
        return parse_list(tokens, pos)
    elif tok_type == ')':
        raise SchemeError("unexpected )")
    elif tok_type == "'":
        pos[0] += 1
        datum = parse_form(tokens, pos)
        return Pair(Symbol('quote'), Pair(datum, NIL))
    elif tok_type == 'string':
        pos[0] += 1
        return tok_val
    elif tok_type == 'word':
        pos[0] += 1
        return parse_word(tok_val)
    else:
        raise SchemeError("unexpected token")

def parse_list(tokens, pos):
    elements = []
    while True:
        if pos[0] >= len(tokens):
            raise SchemeError("unbalanced (")
        tok_type, tok_val = tokens[pos[0]]
        if tok_type == ')':
            pos[0] += 1
            break
        elif tok_type == 'word' and tok_val == '.':
            if not elements:
                raise SchemeError("dot without preceding element")
            pos[0] += 1
            # Parse exactly one datum
            dot_val = parse_form(tokens, pos)
            # Next must be )
            if pos[0] >= len(tokens):
                raise SchemeError("expected ) after dotted value")
            if tokens[pos[0]][0] != ')':
                raise SchemeError("expected ) after dotted value")
            pos[0] += 1
            # Build dotted pair
            result = dot_val
            for elem in reversed(elements):
                result = Pair(elem, result)
            return result
        else:
            elements.append(parse_form(tokens, pos))
    # Build proper list
    result = NIL
    for elem in reversed(elements):
        result = Pair(elem, result)
    return result

def parse_word(word):
    if word == '#t':
        return True
    if word == '#f':
        return False
    if word.startswith('#'):
        raise SchemeError(f"invalid token starting with #: {word}")
    if INT_RE.match(word):
        return int(word)
    return Symbol(word)
```

Now the evaluator:

```python
# ─── Evaluator ────────────────────────────────────────────────────────────────

def is_true(x):
    return not (x is False)

def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)

def cdr_to_list(pair):
    result = []
    while isinstance(pair, Pair):
        result.append(pair.car)
        pair = pair.cdr
    if not isinstance(pair, _Nil):
        raise SchemeError("improper list")
    return result

def to_python_list(x):
    """Convert a Scheme proper list to a Python list."""
    result = []
    while isinstance(x, Pair):
        result.append(x.car)
        x = x.cdr
    if not isinstance(x, _Nil):
        raise SchemeError("not a proper list")
    return result

def list_to_scheme(items):
    """Convert a Python list to a Scheme proper list."""
    result = NIL
    for item in reversed(items):
        result = Pair(item, result)
    return result

def analyze_formals(formals):
    """Returns (required_symbols_list, rest_symbol_or_None)."""
    if isinstance(formals, Symbol):
        return None, formals
    required = []
    rest = None
    cur = formals
    while isinstance(cur, Pair):
        if isinstance(cur.cdr, _Nil):
            required.append(cur.car)
            break
        elif isinstance(cur.cdr, Symbol):
            required.append(cur.car)
            rest = cur.cdr
            break
        else:
            required.append(cur.car)
            cur = cur.cdr
    return required, rest

def check_arity(formals, args):
    if isinstance(formals, Symbol):
        return  # accepts any number
    required, rest = analyze_formals(formals)
    if rest is None:
        if len(args) != len(required):
            raise SchemeError(f"wrong number of arguments: expected {len(required)}, got {len(args)}")
    else:
        if len(args) < len(required):
            raise SchemeError(f"wrong number of arguments: expected at least {len(required)}, got {len(args)}")

def make_call_env(formals, args, parent_env):
    env = Env(parent_env)
    if isinstance(formals, Symbol):
        env.define(formals.name, list_to_scheme(args))
    else:
        required, rest = analyze_formals(formals)
        for i, sym in enumerate(required):
            env.define(sym.name, args[i])
        if rest is not None:
            env.define(rest.name, list_to_scheme(args[len(required):]))
    return env

def is_define_form(form):
    return (isinstance(form, Pair) and 
            isinstance(form.car, Symbol) and 
            form.car.name == 'define')

def get_define_name(form):
    target = form.cdr.car
    if isinstance(target, Symbol):
        return target.name
    elif isinstance(target, Pair):
        if isinstance(target.car, Symbol):
            return target.car.name
    raise SchemeError("invalid define form")

def eval_body(forms, env, tail):
    """Evaluate a body (list of forms) in env. Handle internal defines."""
    if not forms:
        raise SchemeError("empty body")

    # Scan for internal defines
    define_names = []
    for form in forms:
        if is_define_form(form):
            define_names.append(get_define_name(form))

    # Create body environment with pre-bound names
    body_env = Env(env)
    for name in define_names:
        body_env.define(name, UNINITIALIZED)

    # Evaluate forms in order
    for i, form in enumerate(forms):
        is_last = (i == len(forms) - 1)
        if is_define_form(form):
            eval_internal_define(form, body_env)
            if is_last:
                return UNSPECIFIED
        else:
            if is_last and tail:
                return eval(form, body_env, True)
            else:
                eval(form, body_env, False)

    return UNSPECIFIED

def eval_internal_define(expr, body_env):
    target = expr.cdr.car
    if isinstance(target, Symbol):
        # (define name expr)
        if not isinstance(expr.cdr.cdr, Pair):
            raise SchemeError("define: missing expression")
        value = eval(expr.cdr.cdr.car, body_env, False)
        body_env.set(target.name, value)
    elif isinstance(target, Pair):
        # (define (name . formals) body...)
        if not isinstance(target.car, Symbol):
            raise SchemeError("define: invalid name")
        name = target.car.name
        formals = target.cdr
        body = cdr_to_list(expr.cdr.cdr)
        if not body:
            raise SchemeError("define: empty body")
        closure = Closure(formals, body, body_env)
        body_env.set(name, closure)
    else:
        raise SchemeError("define: invalid form")
    return UNSPECIFIED

def eval(expr, env, tail):
    if isinstance(expr, bool):
        return expr
    if isinstance(expr, int):
        return expr
    if isinstance(expr, str):
        return expr
    if isinstance(expr, _Nil):
        return expr
    if isinstance(expr, _Unspecified):
        return expr
    if isinstance(expr, Symbol):
        return env.lookup(expr.name)
    if isinstance(expr, Pair):
        head = expr.car
        if isinstance(head, Symbol):
            name = head.name
            if name == 'quote':
                if not isinstance(expr.cdr, Pair):
                    raise SchemeError("quote: missing datum")
                return expr.cdr.car
            elif name == 'if':
                return eval_if(expr, env, tail)
            elif name == 'lambda':
                return eval_lambda(expr, env)
            elif name == 'define':
                return eval_define(expr, env)
            elif name == 'set!':
                return eval_set(expr, env)
            elif name == 'begin':
                return eval_begin(expr, env, tail)
            elif name == 'cond':
                return eval_cond(expr, env, tail)
            elif name == 'and':
                return eval_and(expr, env, tail)
            elif name == 'or':
                return eval_or(expr, env, tail)
            elif name == 'let':
                return eval_let(expr, env, tail)
            elif name == 'let*':
                return eval_let_star(expr, env, tail)
            elif name == 'letrec':
                return eval_letrec(expr, env, tail)
            elif name == 'apply':
                return eval_apply(expr, env, tail)
        # Procedure application
        return eval_application(expr, env, tail)
    raise SchemeError("malformed expression")

def eval_if(expr, env, tail):
    rest = expr.cdr
    if not isinstance(rest, Pair):
        raise SchemeError("if: malformed")
    test = eval(rest.car, env, False)
    branches = rest.cdr
    if not isinstance(branches, Pair):
        raise SchemeError("if: malformed")
    if is_true(test):
        return eval(branches.car, env, tail)
    else:
        if isinstance(branches.cdr, _Nil):
            return UNSPECIFIED
        return eval(branches.cdr.car, env, tail)

def eval_lambda(expr, env):
    if not isinstance(expr.cdr, Pair):
        raise SchemeError("lambda: malformed")
    formals = expr.cdr.car
    body = cdr_to_list(expr.cdr.cdr)
    if not body:
        raise SchemeError("lambda: empty body")
    return Closure(formals, body, env)

def eval_define(expr, env):
    if not isinstance(expr.cdr, Pair):
        raise SchemeError("define: malformed")
    target = expr.cdr.car
    if isinstance(target, Symbol):
        # (define name expr)
        if not isinstance(expr.cdr.cdr, Pair):
            raise SchemeError("define: missing expression")
        value = eval(expr.cdr.cdr.car, env, False)
        env.define(target.name, value)
    elif isinstance(target, Pair):
        # (define (name . formals) body...)
        if not isinstance(target.car, Symbol):
            raise SchemeError("define: invalid name")
        name = target.car.name
        formals = target.cdr
        body = cdr_to_list(expr.cdr.cdr)
        if not body:
            raise SchemeError("define: empty body")
        closure = Closure(formals, body, env)
        env.define(name, closure)
    else:
        raise SchemeError("define: invalid form")
    return UNSPECIFIED

def eval_set(expr, env):
    if not isinstance(expr.cdr, Pair):
        raise SchemeError("set!: malformed")
    name = expr.cdr.car
    if not isinstance(name, Symbol):
        raise SchemeError("set!: name must be a symbol")
    if not isinstance(expr.cdr.cdr, Pair):
        raise SchemeError("set!: missing expression")
    value = eval(expr.cdr.cdr.car, env, False)
    env.set(name.name, value)
    return UNSPECIFIED

def eval_begin(expr, env, tail):
    forms = cdr_to_list(expr.cdr)
    if not forms:
        raise SchemeError("begin: empty")
    for form in forms[:-1]:
        eval(form, env, False)
    return eval(forms[-1], env, tail)

def eval_cond(expr, env, tail):
    clauses = cdr_to_list(expr.cdr)
    for i, clause in enumerate(clauses):
        if not isinstance(clause, Pair):
            raise SchemeError("cond: malformed clause")
        test = clause.car
        body = cdr_to_list(clause.cdr)
        if isinstance(test, Symbol) and test.name == 'else':
            if not body:
                raise SchemeError("cond: else without expressions")
            for form in body[:-1]:
                eval(form, env, False)
            return eval(body[-1], env, tail)
        val = eval(test, env, False)
        if is_true(val):
            if not body:
                return val
            for form in body[:-1]:
                eval(form, env, False)
            return eval(body[-1], env, tail)
    return UNSPECIFIED

def eval_and(expr, env, tail):
    forms = cdr_to_list(expr.cdr)
    if not forms:
        return True
    for form in forms[:-1]:
        val = eval(form, env, False)
        if not is_true(val):
            return False
    return eval(forms[-1], env, tail)

def eval_or(expr, env, tail):
    forms = cdr_to_list(expr.cdr)
    if not forms:
        return False
    for form in forms[:-1]:
        val = eval(form, env, False)
        if is_true(val):
            return val
    return eval(forms[-1], env, tail)

def eval_let(expr, env, tail):
    if not isinstance(expr.cdr, Pair):
        raise SchemeError("let: malformed")
    first = expr.cdr.car
    if isinstance(first, Symbol):
        # Named let: (let name ((v init)...) body...)
        name = first
        if not isinstance(expr.cdr.cdr, Pair):
            raise SchemeError("named let: malformed")
        bindings = expr.cdr.cdr.car
        body_forms = cdr_to_list(expr.cdr.cdr.cdr)
        if not body_forms:
            raise SchemeError("named let: empty body")

        # Parse bindings and evaluate inits in outer env
        var_names = []
        init_values = []
        cur = bindings
        while isinstance(cur, Pair):
            binding = cur.car
            if not isinstance(binding, Pair) or not isinstance(binding.car, Symbol):
                raise SchemeError("named let: invalid binding")
            var_names.append(binding.car)
            init_values.append(eval(binding.cdr.car, env, False))
            cur = cur.cdr

        # Build formals
        formals = NIL
        for vn in reversed(var_names):
            formals = Pair(vn, formals)

        # Create loop env and closure
        loop_env = Env(env)
        closure = Closure(formals, body_forms, loop_env)
        loop_env.define(name.name, closure)

        # Call the closure
        if tail:
            return TailCall(closure, init_values)
        else:
            call_env = make_call_env(formals, init_values, loop_env)
            return eval_body(body_forms, call_env, False)
    else:
        # Regular let: (let ((v init)...) body...)
        bindings = first
        body_forms = cdr_to_list(expr.cdr.cdr)
        if not body_forms:
            raise SchemeError("let: empty body")

        # Evaluate inits in outer env
        var_names = []
        init_values = []
        cur = bindings
        while isinstance(cur, Pair):
            binding = cur.car
            if not isinstance(binding, Pair) or not isinstance(binding.car, Symbol):
                raise SchemeError("let: invalid binding")
            var_names.append(binding.car.name)
            init_values.append(eval(binding.cdr.car, env, False))
            cur = cur.cdr

        # Create new env
        let_env = Env(env)
        for vn, iv in zip(var_names, init_values):
            let_env.define(vn, iv)

        return eval_body(body_forms, let_env, tail)

def eval_let_star(expr, env, tail):
    if not isinstance(expr.cdr, Pair):
        raise SchemeError("let*: malformed")
    bindings = expr.cdr.car
    body_forms = cdr_to_list(expr.cdr.cdr)
    if not body_forms:
        raise SchemeError("let*: empty body")

    star_env = Env(env)
    cur = bindings
    while isinstance(cur, Pair):
        binding = cur.car
        if not isinstance(binding, Pair) or not isinstance(binding.car, Symbol):
            raise SchemeError("let*: invalid binding")
        name = binding.car.name
        val = eval(binding.cdr.car, star_env, False)
        star_env.define(name, val)
        cur = cur.cdr

    return eval_body(body_forms, star_env, tail)

def eval_letrec(expr, env, tail):
    if not isinstance(expr.cdr, Pair):
        raise SchemeError("letrec: malformed")
    bindings = expr.cdr.car
    body_forms = cdr_to_list(expr.cdr.cdr)
    if not body_forms:
        raise SchemeError("letrec: empty body")

    letrec_env = Env(env)

    # First pass: bind all names to UNINITIALIZED
    names = []
    inits = []
    cur = bindings
    while isinstance(cur, Pair):
        binding = cur.car
        if not isinstance(binding, Pair) or not isinstance(binding.car, Symbol):
            raise SchemeError("letrec: invalid binding")
        name = binding.car.name
        names.append(name)
        inits.append(binding.cdr.car)
        letrec_env.define(name, UNINITIALIZED)
        cur = cur.cdr

    # Second pass: evaluate inits in order
    for name, init in zip(names, inits):
        val = eval(init, letrec_env, False)
        letrec_env.set(name, val)

    return eval_body(body_forms, letrec_env, tail)

def eval_apply(expr, env, tail):
    args_list = cdr_to_list(expr.cdr)
    if len(args_list) < 2:
        raise SchemeError("apply: requires at least 2 arguments")

    proc = eval(args_list[0], env, False)
    regular_args = []
    for arg_expr in args_list[1:-1]:
        regular_args.append(eval(arg_expr, env, False))
    lst = eval(args_list[-1], env, False)

    elements = to_python_list(lst)
    all_args = regular_args + elements

    if isinstance(proc, Closure):
        check_arity(proc.formals, all_args)
        if tail:
            return TailCall(proc, all_args)
        else:
            new_env = make_call_env(proc.formals, all_args, proc.env)
            return eval_body(proc.body, new_env, False)
    elif isinstance(proc, Builtin):
        return proc.func(all_args)
    else:
        raise SchemeError("apply: not a procedure")

def eval_application(expr, env, tail):
    proc = eval(expr.car, env, False)
    args = []
    cur = expr.cdr
    while isinstance(cur, Pair):
        args.append(eval(cur.car, env, False))
        cur = cur.cdr
    if not isinstance(cur, _Nil):
        raise SchemeError("dotted form used as application")

    if isinstance(proc, Closure):
        check_arity(proc.formals, args)
        if tail:
            return TailCall(proc, args)
        else:
            new_env = make_call_env(proc.formals, args, proc.env)
            return eval_body(proc.body, new_env, False)
    elif isinstance(proc, Builtin):
        return proc.func(args)
    else:
        raise SchemeError("not a procedure")

def trampoline(expr, env):
    result = eval(expr, env, True)
    while isinstance(result, TailCall):
        proc = result.proc
        args = result.args
        if isinstance(proc, Closure):
            new_env = make_call_env(proc.formals, args, proc.env)
            result = eval_body(proc.body, new_env, True)
        elif isinstance(proc, Builtin):
            result = proc.func(args)
        else:
            raise SchemeError("not a procedure")
    return result
