Now the display/write functions:

```python
# ─── Display / Write ──────────────────────────────────────────────────────────

def display_repr(x):
    if isinstance(x, bool):
        return '#t' if x else '#f'
    if isinstance(x, int):
        return str(x)
    if isinstance(x, str):
        return x
    if isinstance(x, Symbol):
        return x.name
    if isinstance(x, _Nil):
        return '()'
    if isinstance(x, _Unspecified):
        return ''
    if isinstance(x, Pair):
        return display_pair(x)
    if isinstance(x, (Closure, Builtin)):
        return '#<procedure>'
    return ''

def display_pair(p):
    parts = []
    cur = p
    while isinstance(cur, Pair):
        parts.append(display_repr(cur.car))
        cur = cur.cdr
    if isinstance(cur, _Nil):
        return '(' + ' '.join(parts) + ')'
    else:
        return '(' + ' '.join(parts) + ' . ' + display_repr(cur) + ')'

def write_repr(x):
    if isinstance(x, str):
        escaped = x.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n')
        return '"' + escaped + '"'
    if isinstance(x, Pair):
        return write_pair(x)
    return display_repr(x)

def write_pair(p):
    parts = []
    cur = p
    while isinstance(cur, Pair):
        parts.append(write_repr(cur.car))
        cur = cur.cdr
    if isinstance(cur, _Nil):
        return '(' + ' '.join(parts) + ')'
    else:
        return '(' + ' '.join(parts) + ' . ' + write_repr(cur) + ')'
