Now the builtins:

```python
# ─── Builtins ─────────────────────────────────────────────────────────────────

def make_global_env(output):
    env = Env()

    def add(name, func):
        env.define(name, Builtin(name, func))

    # Type predicates
    def number_check(x):
        if not is_int(x):
            raise SchemeError("expected integer")

    # Arithmetic
    def plus(args):
        result = 0
        for a in args:
            number_check(a)
            result += a
        return result

    def times(args):
        result = 1
        for a in args:
            number_check(a)
            result *= a
        return result

    def minus(args):
        if not args:
            raise SchemeError("-: requires at least 1 argument")
        for a in args:
            number_check(a)
        if len(args) == 1:
            return -args[0]
        result = args[0]
        for a in args[1:]:
            result -= a
        return result

    def quotient_fn(args):
        if len(args) != 2:
            raise SchemeError("quotient: requires 2 arguments")
        a, b = args
        number_check(a)
        number_check(b)
        if b == 0:
            raise SchemeError("quotient: division by zero")
        q = abs(a) // abs(b)
        if (a < 0) ^ (b < 0):
            q = -q
        return q

    def remainder_fn(args):
        if len(args) != 2:
            raise SchemeError("remainder: requires 2 arguments")
        a, b = args
        number_check(a)
        number_check(b)
        if b == 0:
            raise SchemeError("remainder: division by zero")
        q = abs(a) // abs(b)
        if (a < 0) ^ (b < 0):
            q = -q
        return a - q * b

    def modulo_fn(args):
        if len(args) != 2:
            raise SchemeError("modulo: requires 2 arguments")
        a, b = args
        number_check(a)
        number_check(b)
        if b == 0:
            raise SchemeError("modulo: division by zero")
        return a % b

    def make_cmp(op):
        def cmp_fn(args):
            if not args:
                raise SchemeError("comparison: requires at least 1 argument")
            for a in args:
                number_check(a)
            for i in range(len(args) - 1):
                if not op(args[i], args[i+1]):
                    return False
            return True
        return cmp_fn

    # List operations
    def cons(args):
        if len(args) != 2:
            raise SchemeError("cons: requires 2 arguments")
        return Pair(args[0], args[1])

    def car(args):
        if len(args) != 1:
            raise SchemeError("car: requires 1 argument")
        p = args[0]
        if not isinstance(p, Pair):
            raise SchemeError("car: not a pair")
        return p.car

    def cdr(args):
        if len(args) != 1:
            raise SchemeError("cdr: requires 1 argument")
        p = args[0]
        if not isinstance(p, Pair):
            raise SchemeError("cdr: not a pair")
        return p.cdr

    def list_fn(args):
        return list_to_scheme(args)

    def null_fn(args):
        if len(args) != 1:
            raise SchemeError("null?: requires 1 argument")
        return isinstance(args[0], _Nil)

    def pair_fn(args):
        if len(args) != 1:
            raise SchemeError("pair?: requires 1 argument")
        return isinstance(args[0], Pair)

    def list_fn_p(args):
        if len(args) != 1:
            raise SchemeError("list?: requires 1 argument")
        x = args[0]
        while isinstance(x, Pair):
            x = x.cdr
        return isinstance(x, _Nil)

    def length_fn(args):
        if len(args) != 1:
            raise SchemeError("length: requires 1 argument")
        x = args[0]
        count = 0
        while isinstance(x, Pair):
            count += 1
            x = x.cdr
        if not isinstance(x, _Nil):
            raise SchemeError("length: not a proper list")
        return count

    def append_fn(args):
        if not args:
            return NIL
        if len(args) == 1:
            return args[0]
        # All but last must be proper lists
        result = []
        for i in range(len(args) - 1):
            x = args[i]
            while isinstance(x, Pair):
                result.append(x.car)
                x = x.cdr
            if not isinstance(x, _Nil):
                raise SchemeError("append: not a proper list")
        last = args[-1]
        result_scheme = last
        for elem in reversed(result):
            result_scheme = Pair(elem, result_scheme)
        return result_scheme

    def reverse_fn(args):
        if len(args) != 1:
            raise SchemeError("reverse: requires 1 argument")
        x = args[0]
        result = NIL
        while isinstance(x, Pair):
            result = Pair(x.car, result)
            x = x.cdr
        if not isinstance(x, _Nil):
            raise SchemeError("reverse: not a proper list")
        return result

    def apply_fn(args):
        # This is handled by the special form eval_apply
        # But we also need a builtin version for when apply is used as a value
        # Actually, the spec says apply is a special form for tail calls
        # But it's also a builtin? Let me re-read...
        # "A call to apply: (apply f args...) in a tail position calls f as a tail call."
        # This suggests apply is special-cased in the evaluator.
        # But it's also listed under "Lists and pairs" builtins.
        # I'll handle it as a special form in eval, and also as a builtin for when it's used as a value.
        if len(args) < 2:
            raise SchemeError("apply: requires at least 2 arguments")
        proc = args[0]
        regular_args = args[1:-1]
        lst = args[-1]
        elements = to_python_list(lst)
        all_args = list(regular_args) + elements
        if isinstance(proc, Closure):
            check_arity(proc.formals, all_args)
            new_env = make_call_env(proc.formals, all_args, proc.env)
            return eval_body(proc.body, new_env, False)
        elif isinstance(proc, Builtin):
            return proc.func(all_args)
        else:
            raise SchemeError("apply: not a procedure")

    # Equality
    def eq_fn(args):
        if len(args) != 2:
            raise SchemeError("eq?: requires 2 arguments")
        a, b = args
        if isinstance(a, bool) and isinstance(b, bool):
            return a is b
        if is_int(a) and is_int(b):
            return a == b
        if isinstance(a, Symbol) and isinstance(b, Symbol):
            return a.name == b.name
        if isinstance(a, _Nil) and isinstance(b, _Nil):
            return True
        return a is b

    def equal_fn(args):
        if len(args) != 2:
            raise SchemeError("equal?: requires 2 arguments")
        return equal_impl(args[0], args[1])

    def equal_impl(a, b):
        while True:
            if isinstance(a, Pair) and isinstance(b, Pair):
                if not equal_impl(a.car, b.car):
                    return False
                a = a.cdr
                b = b.cdr
            elif isinstance(a, _Nil) and isinstance(b, _Nil):
                return True
            elif isinstance(a, str) and isinstance(b, str):
                return a == b
            elif isinstance(a, Symbol) and isinstance(b, Symbol):
                return a.name == b.name
            elif is_int(a) and is_int(b):
                return a == b
            elif isinstance(a, bool) and isinstance(b, bool):
                return a is b
            elif isinstance(a, _Nil) or isinstance(b, _Nil):
                return False
            else:
                return a is b

    def not_fn(args):
        if len(args) != 1:
            raise SchemeError("not: requires 1 argument")
        return args[0] is False

    def number_p(args):
        if len(args) != 1:
            raise SchemeError("number?: requires 1 argument")
        return is_int(args[0])

    def symbol_p(args):
        if len(args) != 1:
            raise SchemeError("symbol?: requires 1 argument")
        return isinstance(args[0], Symbol)

    def string_p(args):
        if len(args) != 1:
            raise SchemeError("string?: requires 1 argument")
        return isinstance(args[0], str)

    def procedure_p(args):
        if len(args) != 1:
            raise SchemeError("procedure?: requires 1 argument")
        return isinstance(args[0], (Closure, Builtin))

    # Strings
    def string_append(args):
        for s in args:
            if not isinstance(s, str):
                raise SchemeError("string-append: not a string")
        return ''.join(args)

    # Number to string
    def int_to_base(n, radix):
        if n == 0:
            return '0'
        negative = n < 0
        n = abs(n)
        digits = []
        while n > 0:
            d = n % radix
            if d < 10:
                digits.append(chr(ord('0') + d))
            else:
                digits.append(chr(ord('a') + d - 10))
            n //= radix
        result = ''.join(reversed(digits))
        if negative:
            result = '-' + result
        return result

    def number_to_string(args):
        if len(args) == 1:
            n = args[0]
            if not is_int(n):
                raise SchemeError("number->string: not a number")
            return str(n)
        elif len(args) == 2:
            n = args[0]
            radix = args[1]
            if not is_int(n):
                raise SchemeError("number->string: not a number")
            if not is_int(radix):
                raise SchemeError("number->string: radix not an integer")
            if radix not in (2, 8, 10, 16):
                raise SchemeError("number->string: invalid radix")
            return int_to_base(n, radix)
        else:
            raise SchemeError("number->string: wrong number of arguments")

    # Output
    def display_fn(args):
        if len(args) != 1:
            raise SchemeError("display: requires 1 argument")
        output.append(display_repr(args[0]))
        return UNSPECIFIED

    def newline_fn(args):
        if len(args) != 0:
            raise SchemeError("newline: requires 0 arguments")
        output.append('\n')
        return UNSPECIFIED

    # Error
    def error_fn(args):
        if not args:
            raise SchemeError("error: no arguments")
        msg = args[0]
        if not isinstance(msg, str):
            raise SchemeError(str(msg))
        parts = [msg]
        for irritant in args[1:]:
            parts.append(' ')
            parts.append(write_repr(irritant))
        raise SchemeError(''.join(parts))

    # Register all builtins
    add('+', plus)
    add('*', times)
    add('-', minus)
    add('quotient', quotient_fn)
    add('remainder', remainder_fn)
    add('modulo', modulo_fn)
    add('=', make_cmp(lambda a, b: a == b))
    add('<', make_cmp(lambda a, b: a < b))
    add('>', make_cmp(lambda a, b: a > b))
    add('<=', make_cmp(lambda a, b: a <= b))
    add('>=', make_cmp(lambda a, b: a >= b))
    add('cons', cons)
    add('car', car)
    add('cdr', cdr)
    add('list', list_fn)
    add('null?', null_fn)
    add('pair?', pair_fn)
    add('list?', list_fn_p)
    add('length', length_fn)
    add('append', append_fn)
    add('reverse', reverse_fn)
    add('apply', apply_fn)
    add('eq?', eq_fn)
    add('equal?', equal_fn)
    add('not', not_fn)
    add('number?', number_p)
    add('symbol?', symbol_p)
    add('string?', string_p)
    add('procedure?', procedure_p)
    add('string-append', string_append)
    add('number->string', number_to_string)
    add('display', display_fn)
    add('newline', newline_fn)
    add('error', error_fn)

    return env
